type Leaves<T> = T extends string ? T : { [K in keyof T]: Leaves<T[K]> }[keyof T];

/** A namespace in the `backend` scope. */
export type BackendI18nKeysNamespace = keyof typeof BackendI18nKeys;

/** Any key of one namespace, as the string the translator is called with. */
export type BackendI18nKeysKey<N extends BackendI18nKeysNamespace> = Leaves<(typeof BackendI18nKeys)[N]>;
